p="index.html";s=open(p,encoding="utf-8").read()
def rep(o,n,k=1):
    global s;c=s.count(o);assert c==k,(o[:70],c);s=s.replace(o,n)
# Page du book et exécution : textes justes (accidents dans la rentabilité, foule au-delà de la limite, frais, recrue ÷2, qui paie quoi), le technique replié
rep("""votre société paie le courtage, ${dec(COMB,1)} pb du notionnel.""","""votre société paie le courtage, ${dec(COMB*1e4,1)} pb du notionnel.""")
rep("""  return `<p class="note" style="margin:0 0 4px">Valeurs <b>trimestrielles</b>, comme partout dans le jeu. Risque : écart-type du trimestre, book et collatéral compris, bruit d'estimation compris ; sa jauge passe à l'ambre puis au rouge à mesure qu'il monte. Rentabilité : rendement attendu du trimestre — collatéral (et ce que la marge lui retire), impact compris, moins le coût du risque (½ σ²) et la perte moyenne des extrêmes à la probabilité du desk ; ni les accidents de levier ni les squeezes, détaillés dans la fenêtre de chaque marché ; sa jauge est rouge sous zéro et verte au niveau du meilleur concurrent. Traits tous les 5 points. Point jaune pâle : votre fonds juste avant votre dernier changement de position, toutes les autres positions comprises. Les concurrents sont placés à leur couple estimé (risque · rentabilité).</p>""",
    """  return `<p class="note" style="margin:0 0 4px">Valeurs <b>trimestrielles</b>. Risque : l'écart-type du trimestre. Rentabilité : le rendement attendu, coûts et chocs moyens déduits. Les autres points sont vos concurrents.</p><details style="margin:0 0 4px"><summary>Lire le graphique</summary><p class="note">Le risque compte le book, le collatéral et le bruit d'estimation ; sa jauge passe à l'ambre puis au rouge à mesure qu'il monte. La rentabilité compte le collatéral (et ce que la marge lui retire) et l'impact, moins le coût du risque (½ σ²), la perte moyenne des extrêmes à la probabilité du desk et le coût moyen des accidents de levier ; les squeezes sont détaillés dans la fenêtre de chaque marché. Sa jauge est rouge sous zéro et verte au niveau du meilleur concurrent. Traits tous les 5 points. Point jaune pâle : votre fonds juste avant votre dernier changement de position. Les concurrents sont placés à leur couple estimé.</p></details>""")
rep("""Aucun book n'y échappe tout à fait : la fréquence monte avec le carré du risque, la perte avec le risque, et le sang-froid du desk joue sur les deux.</p>`;""","""Aucun book n'y échappe tout à fait : la fréquence monte avec le carré du risque, la perte avec le risque.</p>`;""")
rep("""  <p class="note" style="margin:0 0 4px">Lecture des marchés ${p2(FR.lect)}""","""  <details style="margin:0 0 4px"><summary>d'où elle vient</summary><p class="note" style="margin:0">Lecture des marchés ${p2(FR.lect)}""")
rep("""C'est sur elle que se lit la rentabilité marginale des marchés.</p>""","""C'est sur elle que se lit la rentabilité marginale des marchés.</p></details>""")
rep("""  <p class="note" style="margin:0 0 4px">Book lu par le desk ${dec(FP.book*50,1)} %""","""  <details style="margin:0 0 4px"><summary>d'où il vient</summary><p class="note" style="margin:0">Book lu par le desk ${dec(FP.book*50,1)} %""")
rep("""C'est sur lui que se lit le risque marginal des marchés.</p>""","""C'est sur lui que se lit le risque marginal des marchés.</p></details>""")
rep("""Probabilité d'un accident de levier ce trimestre : ${Math.round(A.p*100)} % — ${Math.round(A.r*100)} % par le risque du book, jamais nul, et ${Math.round(A.m*100)} % par la marge, nul sous ${Math.round(MGZ.watch*100)} %, ${Math.round(MGZ.pmax*100)} % au seuil d'appel. Pour la faire baisser : moins de notionnel, surtout sur les marchés à forte marge (actions, matières premières, crypto).</p>""",
    """Accident de levier ce trimestre : ${Math.round(A.p*100)} % — ${Math.round(A.r*100)} % par le risque du book, ${Math.round(A.m*100)} % par la marge (nulle sous ${Math.round(MGZ.watch*100)} %). Pour la réduire : moins de risque, et moins de notionnel sur les marchés à forte marge (actions, matières premières, crypto).</p>""")
rep("""<p class="note" style="margin:4px 0 0">Toute ligne finit par se voir : ${Math.round(VIS.p0*100)} % par trimestre, plus son poids dans la profondeur du carnet (les marchés étroits d'abord, et tous quand le fonds grossit). Une vente est déclarée ; un achat est vu du prime broker en proportion de la marge utilisée. Le sang-froid du desk (×${dec(motS(),2)}) règle les fuites et la gravité ; seules les lignes à ${Math.round(VIS.show*100)} % ou plus sont listées.</p>""",
    """<details style="margin:4px 0 0"><summary>Comment une ligne se voit</summary><p class="note">Toute ligne finit par se voir : ${Math.round(VIS.p0*100)} % par trimestre, plus son poids dans la profondeur du carnet (les marchés étroits d'abord, et tous quand le fonds grossit). Une vente est déclarée ; un achat est vu du prime broker en proportion de la marge utilisée. Le sang-froid du desk (×${dec(motS(),2)}) règle les fuites et la gravité. Seules les lignes à ${Math.round(VIS.show*100)} % ou plus sont listées.</p></details>""")
rep("""Au-delà de 20 % de risque annuel, les pertes sont amplifiées : un gros book se vend mal quand tout le monde réduit (×${dec(crowd(RS.total),1)} pour le vôtre). La moitié du choc tombe tout de suite ; la suite dépend de votre réaction, comme pour une dépêche. Le prime broker relève ensuite ses marges.""",
    """Au-delà de la limite du comité, les pertes sont amplifiées : un gros book se vend mal quand tout le monde réduit (×${dec(crowd(RS.total),1)} pour le vôtre). La moitié du choc tombe tout de suite ; la suite dépend de votre réaction, comme pour une dépêche.""")
rep("""Vous facturez ${dec((S.budBp*4/100+2),1)} % de frais annuels""","""Vous facturez ${dec(VOL().mgmt*400,1)} % de frais de gestion par an""")
rep("""  <p class="note">Multiplicateur d'exécution appliqué :""","""  <details><summary>Le multiplicateur d'impact</summary><p class="note">Multiplicateur d'impact appliqué :""")
rep("""<em>Votre recrutement du trimestre travaille sur ${INSTR[S.star].sym} : coûts divisés par trois sur ce marché.</em>`:''}</p>`;""","""<em>Votre recrue du trimestre travaille sur ${INSTR[S.star].sym} : impact divisé par deux sur sa classe.</em>`:''}</p></details>`;""")
rep("""${S.star>=0?` Recrue du trimestre sur ${INSTR[S.star].sym} : ÷3.`:''}""","""${S.star>=0?` Recrue du trimestre sur ${INSTR[S.star].sym} : ÷2 sur sa classe.`:''}""")
rep("""Votre société paie les ordres ; le fonds supporte l'impact de marché et les aléas.""","""Votre société paie le courtage ; le fonds paie la fourchette, l'impact de marché et les aléas.""")
# protection
rep("""  <p class="note">La protection rend ${Math.round(h*100)} % du choc immédiat de tout événement extrême du trimestre, ${Math.round(h*50)} % de celui d'une dépêche violente (choc d'au moins 1 σ), et, à la clôture, ${Math.round(h*100)} % de la perte du trimestre au-delà de −${Math.round(PUTK*100)} % : un put sur votre propre book. La suite des mouvements reste à votre charge. Si rien de tout cela n'arrive, la prime est perdue. ${S.prof==='tail'""",
    """  <p class="note">La protection rend ${Math.round(h*100)} % du choc immédiat d'un extrême, ${Math.round(h*50)} % de celui d'une dépêche violente, et ${Math.round(h*100)} % de la perte du trimestre au-delà de −${Math.round(PUTK*100)} %. Si rien n'arrive, la prime est perdue.</p><details><summary>Prix et limites</summary><p class="note">Une dépêche violente est un choc d'au moins 1 σ ; la perte au-delà de −${Math.round(PUTK*100)} % est rendue à la clôture, comme un put sur votre propre book. La suite des mouvements reste à votre charge. ${S.prof==='tail'""")
rep("""elle ne paie que si votre veille vous en dit plus que le marché."}</p>""","""elle ne paie que si votre veille vous en dit plus que le marché."}</p></details>""")
open(p,"w",encoding="utf-8").write(s)
s=open(p,encoding="utf-8").read()
rep("""  <p class="note" style="margin:0 0 6px">Des marchés que votre book ne touche pas : votre desk y repère trois occasions, du coup sûr à l'audacieux. Plus le coup est risqué, plus il rapporte en moyenne. La réussite monte""",
    """  <p class="note" style="margin:0 0 6px">Des marchés que votre book ne touche pas : votre desk y repère trois occasions, du coup sûr à l'audacieux. Plus le coup est risqué, plus il rapporte en moyenne. Verdict à la clôture, sans peser sur le risque ni sur la marge du book. ${ser}.</p>
  <details style="margin:0 0 6px"><summary>Les chances de réussite</summary><p class="note">La réussite monte""")
rep("""jusqu'à ${Math.round(BK.pMax*100)} %. La manœuvre ne pèse ni sur le risque, ni sur la marge du book ; seul le résultat compte, à la clôture. ${ser}.</p>""","""jusqu'à ${Math.round(BK.pMax*100)} %.</p></details>""")
open(p,"w",encoding="utf-8").write(s)
